        "translation": "হে আল্লাহ, সালাত প্রদান করুন মুহাম্মাদের উপরে এবং তাঁর স্ত্রীগণ ও তাঁর সন্তানসন্ততিগণের উপরে, যেমন আপনি সালাত প্রদান করেছেন ইবরাহীমের পরিজনদের উপরে। এবং আপনি বরকত প্রদান করুন মুহাম্মাদের উপরে এবং তাঁর স্ত্রীগণ ও তাঁর সন্তানসন্ততিগণের উপরে, যেমন আপনি বরকত প্রদান করেছেন ইবরাহীমের পরিজনদের উপরে।",
        "virtue": "আবু হুমাইদ সা‘ঈদী (রা.) বর্ণনা করেন: সাহাবীগণ রাসূলুল্লাহ ﷺ-কে জিজ্ঞেস করলেন আমরা কীভাবে আপনার ওপর সালাত (দরূদ) পাঠ করব? তখন তিনি তাঁর পূত-পবিত্র স্ত্রীগণ ও বংশধরদের অন্তর্ভুক্ত করে এ দরূদটি শিক্ষা দেন (সহীহ বুখারী ৩৩৬৯; সহীহ মুসলিম ৪০৭)।",
