    "transliteration": "Allāhumma allif bayna qulūbinā, wa aṣliḥ dhāta bayninā, wahdinā subulas-salām, wa najjinā minaẓ-ẓulumāti ilan-nūr, wa jannibnal-fawāḥisha mā ẓahara minhā wa mā baṭan, wa bārik lanā fī asmā‘inā wa abṣārinā wa qulūbinā wa azwājinā wa dhurriyyātinā, wa tub ‘alaynā innaka Antat-Tawwābur-Raḥīm, waj‘alnā shākirīna lini‘matika muthnīna bihā qābilīhā wa atimmahā ‘alaynā.",
    "translation": "O Allah, unite our hearts in love, mend our mutual relations, guide us to the paths of peace, deliver us from darkness into light, and keep us far from all shameful deeds—apparent and hidden. Bless us in our hearing, our sight, our hearts, our spouses, and our offspring; accept our repentance, for You are the Accepting of Repentance, Most Merciful. Make us grateful for Your favors, praising You for them, welcoming them, and complete Your favor upon us.",
