        "timing": "সালাতের শেষ বৈঠকে দরূদের পর ও পারিবারিক দোয়ায়",
        "translation": "হে আল্লাহ, আপনি আমাদের অন্তরের মধ্যে পরস্পরের প্রতি ভালবাসা ও সম্প্রীতি সৃষ্টি করে দিন। আপনি আমাদের মধ্যে সুসম্পর্ক ও সৌহার্দ্য প্রদান করুন। আপনি আমাদেরকে শান্তির পথে পরিচালিত করুন, আমাদেরকে অন্ধকার থেকে মুক্ত করে আলোয় নিয়ে আসুন, আমাদেরকে প্রকাশ্য ও অপ্রকাশ্য সকল অশ্লীলতা থেকে রক্ষা করুন। আপনি আমাদের শ্রবণযন্ত্রে, আমাদের দৃষ্টিশক্তিতে, আমাদের অন্তরে, আমাদের দাম্পত্য সঙ্গীগণের মধ্যে এবং আমাদের সন্তানগণের মধ্যে বরকত প্রদান করুন। আপনি আমাদের তওবা কবুল করুন। নিশ্চয় আপনি তওবা কবুলকারী পরম করুণাময়। আপনি আমাদেরকে আপনার নিয়ামতের কৃতজ্ঞতা আদায়ের, নিয়ামতের জন্য আপনার প্রশংসা করার এবং নিয়ামতকে সসম্মানে গ্রহণ করার তাওফীক প্রদান করুন এবং আপনি আমাদের জন্য প্রদত্ত আপনার নিয়ামতকে পূর্ণ করুন।",
