        "translation": "হে আল্লাহ, আমি আপনার কাছে চাই সকল কল্যাণ থেকে: নিকটবর্তী কল্যাণ, দূরবর্তী কল্যাণ, আমি যে কল্যাণ সম্পর্কে অবগত আছি এবং আমি যে কল্যাণ সম্পর্কে অবগত নই। আর আমি আপনার আশ্রয় গ্রহণ করছি সকল অকল্যাণ থেকে: নিকটবর্তী অকল্যাণ, দূরবর্তী অকল্যাণ, আমি যে অকল্যাণ সম্পর্কে অবগত আছি এবং আমি যে অকল্যাণ সম্পর্কে অবগত নই। হে আল্লাহ, আমি আপনার কাছে সে সকল কল্যাণ চাই যে সকল কল্যাণ চেয়েছেন আপনার কাছে আপনার বান্দা এবং আপনার নবী (মুহাম্মাদ )। হে আল্লাহ, আমি আপনার কাছে আশ্রয় চাই সে সকল অকল্যাণ থেকে যে সকল অকল্যাণ থেকে আপনার আশ্রয় চেয়েছেন আপনার বান্দা এবং আপনার নবী (মুহাম্মাদ )। হে আল্লাহ, আমি আপনার কাছে চাই জান্নাত এবং জান্নাতের নিকটে নিয়ে যায় এরূপ সকল কথা বা কাজের তাওফীক। এবং আমি আপনার আশ্রয় চাই জাহান্নাম থেকে এবং সেই সব কথা বা কাজ থেকে যা জাহান্নামের কাছে নিয়ে যায়। আর আমি আপনার নিকট প্রার্থনা করি যে, আপনি আমার জন্য যা কিছু ভাগ্য নির্ধারণ করেছেন সব কিছুর চূড়ান্ত পরিণতি আমার জন্য মঙ্গলময় কল্যাণকর করে দিন।",
        "virtue": "আয়েশা (রা.) বলেন: আমি সালাতে দোয়া করছিলাম তখন রাসূলুল্লাহ ﷺ আমাকে বললেন, “তুমি সব কল্যাণ অন্তর্ভুক্তকারী (জাওয়ামি‘উল কালিম) এই পূর্ণাঙ্গ দোয়াটি পড়বে”—এরপর নবীজী ﷺ তাঁকে এ মহান দোয়াটি শিক্ষা দেন (ইবনে মাজাহ ৩৮৪৬; সহীহ ইবনে হিব্বান ৮৬৯; মুসতাদরাক হাকিম ১/৭০২)।",
