    "arabic": "(بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ) اَللّٰهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ وَنُثْنِىْ عَلَيْكَ (وَنَشْكُرُكَ) وَلاَ نَكْفُرُكَ، وَنَخْلَعُ وَنَتْرُكُ مَنْ يَفْجُرُكَ اَللّٰهُمَّ إِيَّاكَ نَعْبُدُ وَلَكَ نُصَلِّى وَنَسْجُدُ وَلَكَ نَسْعَى وَنَحْفِدُ نَخْشَى عَذَابَكَ الْجِدَّ وَنَرْجُوْ رَحْمَتَكَ إِنَّ عَذَابَكَ بِالْكَافِرِيْنَ مُلْحِقٌ.\nاَللّٰهُمَّ اغْفِرْ لَنَا وَلِلْمُؤْمِنِيْنَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِيْنَ وَالْمُسْلِمَاتِ وَأَلِّفْ بَيْنَ قُلُوبِهِمْ وَأَصْلِحْ ذَاتَ بَيْنِهِمْ وَانْصُرْهُمْ عَلَى عَدُوِّكَ وَعَدُوِّهِمْ اَللّٰهُمَّ الْعَنْ كَفَرَةَ أَهْلِ الْكِتَابِ الَّذِيّنَ يَصُدُّوْنَ عَنْ سَبِيْلِكَ وَيُكُذِّبُوْنَ رُسُلَكَ وَيُقَاتِلُوْنَ أَوْلِيَاءَكَ اَللّٰهُمَّ خَالِفْ بَيْنَ كَلِمَتِهِمَ وَزَلْزِلْ أَقْدَامَهُمْ وَأَنْزِلْ بِهِمْ بَأْسَكَ الَّذِىْ لَا تَرُدُّهُ عَنِ الْقَوْمِ الْمُجْرِمِيْنَ",
    "transliteration": "(Bismillāhir-Raḥmānir-Raḥīm) Allāhumma innā nasta‘īnuka wa nastaghfiruka wa nuthnī ‘alayka (wa nashkuruka) wa lā nakfuruk, wa nakhla‘u wa natruku man yafjuruk. Allāhumma iyyāka na‘budu wa laka nuṣallī wa nasjudu wa ilayka nas‘ā wa naḥfid, nakhshā ‘adhābakal-jidda wa narjū raḥmatak, inna ‘adhābaka bil-kāfirīna mulḥiq. Allāhumma-ghfir lanā wa lil-mu’minīna wal-mu’mināti wal-muslimīna wal-muslimāt, wa allif bayna qulūbihim wa aṣliḥ dhāta baynihim wanṣurhum ‘alā ‘aduwwika wa ‘aduwwihim...",
