        "timing": "বিতরের কুনূতে ও মুসলিম উম্মাহর বিপদে কুনূতে নাযিলায়",
        "translation": "হে আল্লাহ, আমরা আপনার কাছে সাহায্য প্রার্থনা করছি, আপনার কাছে ক্ষমা প্রার্থনা করছি, আপনার প্রশংসা ও গুণকীর্তন করছি। আমরা আপনার কৃতজ্ঞতা প্রকাশ করি এবং আপনার প্রতি অকৃতজ্ঞতা-অবিশ্বাস প্রকাশ করি না। আমরা বিচ্ছিন্ন হই এবং পরিত্যাগ করি তাকে যে আপনার অবাধ্য হয়। হে আল্লাহ, আমরা কেবলমাত্র আপনারই ইবাদত করি, কেবলমাত্র আপনার জন্যই সালাত আদায় করি এবং সাজদা করি, শুধু আপনার দিকেই ধাবিত হই এবং আপনার আনুগত্যেই কর্ম করি। আমরা আপনার প্রকৃত শাস্তির ভয় করি এবং আপনার রহমত আশা করি। নিশ্চয় আপনার শাস্তি কাফিরদেরকে স্পর্শ করবে।”\nহে আল্লাহ, ক্ষমা করুন আমাদেরকে, এবং মুমিন পুরুষদেরকে এবং মুমিন নারীদেরকে, এবং মুসলিম পুরুষদেরকে এবং মুসলিম নারীদেরকে, তাদের অন্তরের মধ্যে সম্প্রীতি প্রদান করুন, তাদের আভ্যন্তরীণ সম্পর্ক সুন্দর করে দিন, আপনার ও তাদের শত্র“দের উপর তাদের বিজয় প্রদান করুন। হে আল্লাহ, যে সকল আহল কিতাব আপনার পথ থেকে মানুষদেরকে বাধা দেয়, আপনার রাসূলগণকে অবিশ্বাস করে এবং আপনার ওলীগণের সাথে যুদ্ধ করে তাদের অভিশপ্ত করুন, তাদের মধ্যে অনৈক্য সৃষ্টি করুন, তাদের পদসমূহ কম্পমান করুন, তাদের উপর আপনার শাস্তি নাযিল করুন, যে শাস্তি অপ্রতিরোধ্যভাবে পাপাচারী সম্প্রদায়কে পাকড়াও করে।",
        "virtue": "প্রসিদ্ধ তাবেয়ী উবাইদ ইবনে উমাইর (রহ.) বলেন: আমি হযরত উমর (রা.)-এর পেছনে ফজরের সালাত আদায় করলাম; তিনি কুনূতে নাযিলা হিসেবে এই মহান কুনূত পাঠ করেন। প্রথম অংশটি ইমাম আবু হানীফা (রহ.) সহ অনেক ফকীহ বিতরের কুনূত হিসেবেও পাঠ করার উৎসাহ দিয়েছেন (রাহে বেলায়াত - যিকর নং ৮৫)।",
