    "arabic": "رَبِّ أَعِنِّيْ وَلاَ تُعِنْ عَلَيَّ وَانْصُرْنِيْ وَلا تَنْصُرْ عَلَيَّ وَامْكُرْ لِيْ وَلا تَمْكُرْ عَلَيَّ وَاهْدِنِيْ وَيَسِّرِ الْهُدَى لِيْ (إِلَيَّ) وَانْصُرْنِيْ عَلَی مَنْ بَغَى عَلَيَّ رَبِّ اجْعَلْنِيْ لَكَ شَكَّارًا لَكَ ذَكَّارًا لَكَ رَهَّابًا لَكَ مِطْوَاعًا لَكَ مُخْبِتًا إِلَيْكَ أَوَّاهًا مُنِيْبًا رَبِّ تَقَبَّلْ تَوْبَتِيْ وَاغْسِلْ حَوْبَتِي وَأَجِبْ دَعْوَتِيْ وَثَبِّتْ حُجَّتِيْ وَسَدِّدْ لِسَانِيْ وَاهْدِ قَلْبِيْ وَاسْلُلْ سَخِيْمَةَ قَلْبِيْ (صَدْرِيْ",
    "transliteration": "Rabbi a‘innī wa lā tu‘in ‘alayya, wanṣurnī wa lā tanṣur ‘alayya, wamkur lī wa lā tamkur ‘alayya, wahdinī wa yassiril-hudā lī, wanṣurnī ‘alā man baghā ‘alayya. Rabbi-j‘alnī laka shakkāran laka dhakkāran laka rahhāban laka miṭwā‘an laka mukhbitan ilayka awwāhan munībā. Rabbi taqabbal tawbatī waghsil ḥawbatī wa ajib da‘watī wa thabbit ḥujjatī wa saddid lisānī wahdi qalbī waslul sakhīmata ṣadrī.",
    "translation": "My Lord, help me and do not help against me; grant me victory and do not grant victory against me; plan for me and do not plan against me; guide me and make guidance easy for me; and grant me victory over whoever transgresses against me. My Lord, make me ever grateful to You, ever remembering You, ever in awe of You, ever obedient to You, ever humble before You, earnestly returning and repentant to You. My Lord, accept my repentance, wash away my sins, answer my prayer, strengthen my proof, make my tongue speak truth, guide my heart, and remove all malice and rancor from my chest.",
