        "title": "বিতর ও দোয়ার সর্বব্যাপী নবী-দোয়া #৫ (রব্বি আ‘ইন্নী ওয়া লা তু‘ইন আলাইয়্যা)",
        "timing": "বিতরের কুনূতে ও ব্যক্তিগত দোয়ায়",
        "translation": "হে আমার প্রতিপালক, আপনি আমাকে শক্তি-সহায়তা প্রদান করুন, আর আমার বিরুদ্ধে সহায়তা প্রদান করবেন না। এবং আপনি আমাকে সাহায্য করুন, আর আমার বিরুদ্ধে সাহায্য করবেন না। এবং আপনি আমার জন্য কৌশল করুন, আর আমার বিরুদ্ধে কৌশল করবেন না। এবং আপনি আমাকে হেদায়াত করুন এবং আমার জন্য হেদায়াত সহজ করুন। আপনি আমাকে সাহায্য করুন যে আমার উপর অত্যাচার করেছে তার বিরুদ্ধে। হে আমার প্রতিপালক, আপনি আমাকে বানিয়ে দিন আপনার জন্য অধিক কৃতজ্ঞতা প্রকাশকারী, আপনার অধিক যিকরকারী, আপনার প্রতি অধিক ভীতিসম্পন্ন, আপনার অধিক আনুগত্যকারী, আপনার প্রতি বিনয়ী এবং আপনার দিকে বেশি বেশি তাওবা কারী। হে আমার প্রতিপালক, আপনি কবুল করুন আমার তাওবা, ধুয়ে দিন আমার পাপ, কবুল করুন আমার দু‘আ, প্রতিষ্ঠিত করুন আমার প্রমাণ, পবিত্র-সুসংরক্ষিত করুন আমার জিহ্বা, সুপথে পরিচালিত করুন আমার অন্তর, বের করে দিন আমার অন্তরের সব হিংসা, বিদ্বেষ ও সংকীর্ণতা।",
        "virtue": "ইবনে আব্বাস (রা.) থেকে সহীহ সনদে বর্ণিত রাসূলুল্লাহ ﷺ-এর অনন্য প্রিয় একটি দোয়া—যাতে কৃতজ্ঞতা, যিকির, আল্লাহভীতি, সত্যকথা, তাওবা কবুল এবং অন্তর থেকে হিংসা-বিদ্বেষ ও সংকীর্ণতা দূর করার প্রার্থনা রয়েছে। বিতরের কুনূতে বা যেকোনো দোয়ায় পাঠ করা অত্যন্ত উপকারী (ইবনে মাজাহ ৩৮৩০, তিরমিযী ৩৫৫১, আবু দাউদ ১৫১০)।",
