        "virtue": "আবু যর (রা.) ও মুআয ইবনে জাবাল (রা.) থেকে বর্ণিত: যে ব্যক্তি ফজর ও মাগরিবের সালাতের পর কথা বলার আগে ১০ বার এটি পাঠ করবে, তার জন্য ১০টি নেকী লেখা হবে, ১০টি গুনাহ মোছা হবে, ১০টি মর্যাদা বৃদ্ধি পাবে এবং সে শয়তান ও সকল অনিষ্ট থেকে সুরক্ষিত থাকবে (তিরমিযী ৩৪৭৪; আহমাদ ৪/২২৭; হিসনুল মুসলিম #৬৮ দ্রষ্টব্য)।",
