          "প্রতিদিন মাত্র ১০ বার পাঠে ১০ নেকী, ১০ গুনাহ মাফ ও ১০ মর্যাদা বৃদ্ধি হয়।",
          "সকাল ও সন্ধ্যায় সকল বিপদ, অকল্যাণ ও শয়তানের চক্রান্ত থেকে রক্ষা করে।"
