        "virtue": "Narrated by Abu Dharr (RA) and Mu‘adh ibn Jabal (RA): reciting this 10 times after Fajr and Maghrib writes 10 good deeds, erases 10 sins, raises 10 degrees, and guards against every harm and Shaytan all day or night (at-Tirmidhi 3474; Musnad Ahmad; see Hisnul Muslim #68).",
