    "transliteration": "Bismillāhir-Raḥmānir-Raḥīm. Qul yā ayyuhal-kāfirūn. Lā a‘budu mā ta‘budūn. Wa lā antum ‘ābidūna mā a‘bud. Wa lā ana ‘ābidum-mā ‘abattum. Wa lā antum ‘ābidūna mā a‘bud. Lakum dīnukum wa liya dīn.",
