    "virtue": "Nawfal al-Ashja‘i (RA) narrated that the Prophet ﷺ told him: “Recite Surah al-Kafirun and then go to sleep, for it is a declaration of complete innocence from Shirk (polytheism)” (at-Tirmidhi 3403; Abu Dawud 5055; Ibn Hibban; graded Hasan/Sahih; Rahe Belayat #150).",
