        "virtue": "আবু হুরাইরা (রা.) থেকে বর্ণিত: রাসূলুল্লাহ ﷺ ঘুমানোর সময় বা রাতে আমরণ চোখ-কান সুস্থ রাখা ও শত্রুর বিরুদ্ধে সাহায্যের জন্য এ দোয়া করতেন (মুসতাদরাক হাকিম ২/১৫৪; আলবানী, সহীহুল জামে ১/২৭২; নাবাবী, আল-আযকার পৃ. ১৪২; রাহে বেলায়াত - যিকর নং ১৬১)।",
