    "transliteration": "Allāhumma innī a‘ūdhu bika minal-‘ajzi wal-kasali wal-jubni wal-bukhli wal-harami wa ‘adhābil-qabr. Allāhumma āti nafsī taqwāhā wa zakkihā Anta khayru man zakkāhā Anta waliyyuhā wa mawlāhā. Allāhumma innī a‘ūdhu bika min ‘ilmin lā yanfa‘u wa min qalbin lā yakhsha‘u wa min nafsin lā tashba‘u wa min da‘watin lā yustajābu lahā.",
    "translation": "O Allah, I seek refuge in You from incapacity, laziness, cowardice, miserliness, senility, and the punishment of the grave. O Allah, grant my soul its Taqwa and purify it; You are the Best of those who purify it, You are its Guardian and Master. O Allah, I seek refuge in You from knowledge that brings no benefit, from a heart that does not humble itself, from a soul that is never satisfied, and from a supplication that goes unanswered.",
