        "virtue": "উমর ইবনুল খাত্তাব (রা.) থেকে বর্ণিত সূরা মুমিনুনের শুরুর ১০টি আয়াত নাযিলের সময় রাসূলুল্লাহ ﷺ-এর পঠিত প্রসিদ্ধ দোয়া। শাইখ আব্দুল কাদির আরনাউত একে হাসান বলেছেন এবং শাইখ আলবানী সনদে দুর্বলতা উল্লেখ করেছেন; দোয়ার অর্থ অত্যন্ত সুন্দর ও জনপ্রিয় (তিরমিযী ৩১৭৩; আহমাদ ১/৩৪; রাহে বেলায়াত - দু‘আ ৫)।",
