        "timing": "কবর যিয়ারতের সময় (মৃদু কণ্ঠে মৃতদের জন্য মাগফিরাত কামনায়)",
        "translation": "তোমাদের উপর সালাম, হে মুমিন গৃহবাসিগণ। তোমাদেরকে যা প্রতিশ্রতি দেওয়া হয়েছিল তা তোমাদের কছে এসেছে, আগামী দিনের জন্য তোমাদের অপেক্ষায় রাখা হয়েছে। আর আল্লাহর ইচ্ছায় আমরা তোমাদের সাথে মিলিত হব। হে আল্লাহ আপনি বাকীর গোরস্থানের বাসিন্দাদেরকে ক্ষমা করুন।",
