    "transliteration": "Allāhumma-qsim lanā min khashyatika mā yaḥūlu baynanā wa bayna ma‘āṣīk, wa min ṭā‘atika mā tuballighunā bihi jannatak, wa minal-yaqīni mā tuhawwinu bihi ‘alaynā muṣībātid-dunyā, wa matti‘nā bi-asmā‘inā wa abṣārinā wa quwwatinā mā aḥyaytanā waj‘alhul-wāritha minnā, waj‘al tha’ranā ‘alā man ẓalamanā wanṣurnā ‘alā man ‘ādānā, wa lā taj‘al muṣībatanā fī dīninā, wa lā taj‘alid-dunyā akbara hamminā wa lā mablagha ‘ilminā, wa lā tusalliṭ ‘alaynā man lā yarḥamunā.",
    "translation": "O Allah, apportion to us of fear of You that which comes between us and disobeying You; of obedience to You that which brings us to Your Paradise; and of certainty that which makes the calamities of this world easy for us to bear. Grant us enjoyment of our hearing, our sight, and our strength for as long as You keep us alive, and make it our heir (keep them sound until death). Place our vengeance upon those who wrong us, grant us victory over those who show hostility to us, do not make our calamity be in our religion, do not make the worldly life our greatest concern nor the utmost limit of our knowledge, and do not give power over us to anyone who will have no mercy upon us.",
