        "translation": "হে আল্লাহ, আপনি আমাদেরকে আপনার ভয় করার তাওফীক দিন যে ভয় আমাদেরকে আপনার অবাধ্যতা থেকে রক্ষা করবে। এবং আপনি আমাদেরকে আপনার আনুগত্য করার তাওফীক প্রদান করুন, যে আনুগত্যের দ্বারা আপনি আমাদেরকে আপনার জান্নাতে পৌঁছাবেন। এবং আপনি আমাদেরকে দৃঢ়বিশ্বাস প্রদান করুন, যে বিশ্বাস আমাদের জন্য দুনিয়ার বিপদ-আপদকে সহজ করে দেবে। আপনি আমাদের শ্রবণশক্তি, দৃষ্টিশক্তি ও দেহের শক্তিকে আমাদের জন্য মরণ পর্যন্ত অক্ষুণœ রাখুন এবং এগুলোকে বহাল রেখে আমাদের মৃত্যু দান করুন। যারা আমাদের জুলুম করেছে তাদের উপর আমাদের প্রতিশোধ অর্পণ করুন এবং যারা আমাদের শত্র“তা করেছে তাদের বিরুদ্ধে আমাদের সাহায্য করুন। আমাদের দীনকে বিপদযুক্ত করবেন না, দুনিয়াকে আমাদের চিন্তাভাবনার মূল বিষয় বানাবেন না এবং আমাদের জ্ঞানকে দুনিয়ার মধ্যে সীমাবদ্ধ রাখবেন না। আমাদের প্রতি মমতাবিহীন কাউকে আমাদের উপর ক্ষমতাবান করবেন না।",
